import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.CWWEQfK7.js";const k=JSON.parse('{"title":"搭建本地开发环境","description":"为六个独立仓库准备依赖、基础设施和进程，并逐层确认本地环境可用。","frontmatter":{"page_id":"development-local-setup","title":"搭建本地开发环境","description":"为六个独立仓库准备依赖、基础设施和进程，并逐层确认本地环境可用。"},"headers":[],"relativePath":"development/local-setup.md","filePath":"development/local-setup.md","lastUpdated":1786290726000}'),p={name:"development/local-setup.md"};function l(t,s,h,r,d,c){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="搭建本地开发环境" tabindex="-1">搭建本地开发环境 <a class="header-anchor" href="#搭建本地开发环境" aria-label="Permalink to &quot;搭建本地开发环境&quot;">​</a></h1><p>当前完整开发环境面向能够访问 Ershu 私有组件源的维护者。后端安装清单锁定了私有 Git 地址，因此仅克隆公开组合仓库还不能完成安装。不要用未经固定的本地兄弟目录替换锁定依赖。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>Python 3.14 或更高版本；</li><li>UV，用于安装和运行 Python 项目；</li><li>Node.js 24 与 npm，用于前端；</li><li>Docker 与 Docker Compose，用于 PostgreSQL、Redis 和 Milvus；</li><li>能读取锁文件中 Ershu 组件源的 SSH 凭据；</li><li>五个模块和 <code>ershu</code> 组合仓库的匹配提交。</li></ul><p>源码应作为六个平级目录存在，而不是嵌套成一个总仓库：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>workspace/</span></span>
<span class="line"><span>├── ershu/</span></span>
<span class="line"><span>├── core/</span></span>
<span class="line"><span>├── api/</span></span>
<span class="line"><span>├── worker/</span></span>
<span class="line"><span>├── mcp/</span></span>
<span class="line"><span>└── frontend/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>每个目录都有自己的分支、安装清单和提交历史。先在每个仓库运行 <code>git status --short --branch</code>，确认分支和未提交修改，再开始操作。</p><h2 id="用组合仓库启动完整后端" tabindex="-1">用组合仓库启动完整后端 <a class="header-anchor" href="#用组合仓库启动完整后端" aria-label="Permalink to &quot;用组合仓库启动完整后端&quot;">​</a></h2><p>以下命令在 <code>ershu</code> 目录中的 Bash shell 运行；复制后必须替换所有安全占位值。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>.env.compose</code> 为 PostgreSQL 与 MinIO 提供凭据。<code>.env</code> 为后端进程提供数据库、Redis、Milvus、会话、加密、MCP 和 Worker 设置。示例中的 <code>replace-me</code>、固定弱口令和空生产必填项都不能直接使用。</p><p>启动基础设施：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>成功时，PostgreSQL、Redis、Milvus、etcd 和 MinIO 容器会启动；带健康检查的服务最终应显示为健康。若基础设施未就绪，先查看 <code>docker compose --env-file .env.compose logs</code>，不要继续迁移。</p><p>安装锁定的后端组合并升级数据库：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-extras</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> heads</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> head</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>ershu-db heads</code> 应能读取打包进 Core 的升级记录。升级成功后，再分别打开终端启动进程：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 B</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-mcp</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 C</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-worker</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 D；只有需要自动轮询时才启动</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api-poller</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>API 默认监听 <code>127.0.0.1:8000</code>，MCP 默认监听 <code>127.0.0.1:8001</code>。用下面的存活检查确认两个 HTTP 进程已经响应：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8001/health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>两者都应返回 <code>status</code> 为 <code>ok</code>。这只证明进程存活，不证明数据库、Milvus、模型通道或 Worker 已完成业务就绪。</p><h2 id="启动前端" tabindex="-1">启动前端 <a class="header-anchor" href="#启动前端" aria-label="Permalink to &quot;启动前端&quot;">​</a></h2><p>在独立的 <code>frontend</code> 目录运行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>开发服务器默认位于 <code>http://localhost:3000</code>，并把 <code>/api</code> 代理到 <code>http://localhost:8000</code>，把 <code>/mcp</code> 代理到 <code>http://127.0.0.1:8001</code>。服务地址不同时，只修改 <code>.env.local</code> 中对应的开发代理变量。</p><p>首次打开 <code>http://localhost:3000/#/zh/setup-admin</code>。没有用户时会进入首位管理员设置；创建成功后进入登录或项目界面。Ershu 不开放自助公开注册，后续账号由管理员创建。</p><h2 id="单独开发一个后端模块" tabindex="-1">单独开发一个后端模块 <a class="header-anchor" href="#单独开发一个后端模块" aria-label="Permalink to &quot;单独开发一个后端模块&quot;">​</a></h2><p>在目标仓库按锁文件安装，不把其他模块源码临时塞进导入路径：</p><table tabindex="0"><thead><tr><th>模块</th><th>安装命令</th><th>最小验证</th></tr></thead><tbody><tr><td>Core</td><td><code>uv sync --frozen</code></td><td><code>uv run pytest -m &quot;not integration&quot;</code></td></tr><tr><td>API</td><td><code>uv sync --extra dev --frozen</code></td><td><code>uv run --extra dev pytest -q</code></td></tr><tr><td>Worker</td><td><code>uv sync --extra dev --frozen</code></td><td><code>uv run pytest -q</code></td></tr><tr><td>MCP</td><td><code>uv sync --frozen</code></td><td><code>uv run pytest -q</code></td></tr></tbody></table><p>Core、API、Worker 和 MCP 的锁文件固定了相互匹配的 Core 提交。修改 Core 后，应先提交并更新消费仓库的依赖与锁文件，再做跨仓验收。</p><h2 id="确认环境真的可用" tabindex="-1">确认环境真的可用 <a class="header-anchor" href="#确认环境真的可用" aria-label="Permalink to &quot;确认环境真的可用&quot;">​</a></h2><p>按由近到远的顺序检查：</p><ol><li>基础设施容器健康，数据库升级到当前 head；</li><li>API 和 MCP 存活地址返回 <code>ok</code>；</li><li>前端能打开，并完成首位管理员流程；</li><li>管理员能创建并测试模型通道；</li><li>能添加一个测试仓库并通过仓库验证；</li><li>创建全项目运行后，状态从排队进入运行，最终得到明确结果；</li><li>完成后能打开文档，并取得带来源位置的搜索结果。</li></ol><p>某一步失败时停止向后排查。进程存活但运行一直排队，首先确认 Worker；文档阶段失败，先确认模型通道；语义检索失败，先确认 Milvus 与嵌入设置。</p><blockquote><p>事实来源：六个仓库的安装清单、锁文件、README、进程入口、Compose 文件、健康路由和持续集成配置。</p></blockquote>`,35)])])}const u=a(p,[["render",l]]);export{k as __pageData,u as default};
